// Unmarshal appends one row to c per entity in rec, projecting
// the boxer.facts columns through factsschema/ra. Thin wrapper
// around NotebookLaunchFillFromArrow — the per-row decode lives there.
func (c *NotebookLaunchColumns) Unmarshal(rec arrow.Record) (err error) {
	r := newNotebookLaunchReader()
	defer r.release()
	err = r.loadFromRecord(rec)
	if err != nil {
		return
	}
	n := r.EntityId.Len()
	err = NotebookLaunchFillFromArrow(
		c,
		n,
		r.EntityId.ValueId,
		r.EntityId.ValueNaturalKey,
		r.EntityTimestamp.ValueTs,
		r.TextArray.Attributes, r.TextArray.Memberships,
		r.U64Array.Attributes, r.U64Array.Memberships,
		r.I64Array.Attributes, r.I64Array.Memberships,
		r.StringArray.Attributes, r.StringArray.Memberships,
	)
	return
}

// --- buscodec.CodecI bridge. ---

// NotebookLaunchCodec is the buscodec.CodecI bridge for NotebookLaunch. Encodes one row
// through dml_cbor; decodes via cborarrow.Convert + ra-Unmarshal +
// Row(0). Auto-registered in init() so callers using buscodec.Encode
// / Decode route through here instead of the CBOR fallback.
type NotebookLaunchCodec struct{}

var _ buscodec.CodecI = (*NotebookLaunchCodec)(nil)

// notebookLaunchBusCodec is the package-local singleton wired into buscodec.
var notebookLaunchBusCodec = &NotebookLaunchCodec{}

func (inst *NotebookLaunchCodec) Name() (n string) {
	n = "notebookLaunch-sparse-cbor"
	return
}

func (inst *NotebookLaunchCodec) ContentType() (ct string) {
	ct = "application/x-runtime-facts+rb;kind=notebookLaunch"
	return
}

func (inst *NotebookLaunchCodec) Encode(v any) (b []byte, err error) {
	var row NotebookLaunch
	switch x := v.(type) {
	case NotebookLaunch:
		row = x
	case *NotebookLaunch:
		if x == nil {
			err = eh.Errorf("launchcfg: Encode nil *NotebookLaunch")
			return
		}
		row = *x
	default:
		err = eh.Errorf("launchcfg: Encode requires NotebookLaunch or *NotebookLaunch, got %T", v)
		return
	}
	cols := &NotebookLaunchColumns{}
	cols.Append(row)
	var buf bytes.Buffer
	err = cols.Marshal(&buf)
	if err != nil {
		err = eh.Errorf("launchcfg: Encode marshal: %w", err)
		return
	}
	b = buf.Bytes()
	return
}

func (inst *NotebookLaunchCodec) Decode(b []byte, v any) (err error) {
	target, ok := v.(*NotebookLaunch)
	if !ok {
		err = eh.Errorf("launchcfg: Decode requires *NotebookLaunch, got %T", v)
		return
	}
	var arrowBuf bytes.Buffer
	err = cborarrow.Convert(bytes.NewReader(b), &arrowBuf)
	if err != nil {
		err = eh.Errorf("launchcfg: Decode cborarrow: %w", err)
		return
	}
	rd, err := ipc.NewReader(&arrowBuf)
	if err != nil {
		err = eh.Errorf("launchcfg: Decode ipc reader: %w", err)
		return
	}
	defer rd.Release()
	if !rd.Next() {
		err = eh.Errorf("launchcfg: Decode expected one Arrow record, got none")
		return
	}
	rec := rd.RecordBatch()
	defer rec.Release()
	cols := &NotebookLaunchColumns{}
	err = cols.Unmarshal(rec)
	if err != nil {
		err = eh.Errorf("launchcfg: Decode unmarshal: %w", err)
		return
	}
	if cols.Len() != 1 {
		err = eb.Build().Int("got", cols.Len()).Errorf("launchcfg: Decode expected 1 row")
		return
	}
	*target = cols.Row(0)
	return
}
